cat > /tmp/patch_scratchpad_intro.py <<'__PATCH_INTRO__'
from pathlib import Path
import json
app=Path('workspaces/programs/scratchpad/scratchpad.js')
s=app.read_text()
old_import='const {spawnSync}=require("node:child_process");'
if s.count(old_import)!=1: raise SystemExit('Unexpected application import structure')
s=s.replace(old_import,old_import+'\nconst fs=require("node:fs");\nconst path=require("node:path");',1)
old='''function menu(){
 return {schema:"terminals.scratchpad.operation-menu.v1",menu:c.menu("Scratchpad",["New scratchpad","Edit scratchpad","Submit complete or partial JSON","Complete program","Terminate program"]),operations:["new","edit","new_entry","edit_entry","submit_json"]};
}'''
new='''function menu(){
 const candidates=fs.readdirSync(__dirname,{withFileTypes:true})
  .filter(entry=>entry.isFile()&&entry.name.endsWith("-selection.json"));
 const intros=[];
 for(const file of candidates){
  let document;
  try{document=JSON.parse(fs.readFileSync(path.join(__dirname,file.name),"utf8"));}
  catch(e){fail("INVALID_INTERFACE","Invalid JSON interface: "+file.name);}
  if(document?.role==="intro")intros.push({filename:file.name,document});
 }
 if(intros.length!==1)fail("INVALID_INTERFACE","Expected exactly one introductory selection JSON interface");
 const {filename,document}=intros[0];
 const screen=document.menu;
 const meta=screen?.comment,selection=screen?.selection;
 if(document.schema!=="terminals.scratchpad.operation-menu.v1"||document.version!=="1.0.0"||
    screen?.schema!=="terminals.selection.compiled-tags.v1"||
    meta?.version!=="0.2.0"||typeof meta.createdAt!=="string"||typeof meta.spec!=="string"||
    !c.isObject(selection)||!c.nonempty(selection.shortTitle)||!c.nonempty(selection.title)||
    !selection.shortTitle.endsWith("-selection")||filename!==selection.shortTitle+".json"||
    !Array.isArray(selection.options)||!selection.options.length)
  fail("INVALID_INTERFACE","Introductory interface metadata or shortTitle filename invalid");
 for(const [index,option] of selection.options.entries()){
  if(!c.isObject(option)||option.id!==index||!c.nonempty(option.option))
   fail("INVALID_INTERFACE","Selection options must have consecutive numeric IDs and text");
 }
 const instruction=selection.instruction;
 if(instruction?.SELECT?.by!=="id"||instruction.SELECT.use!=="single-select"||
    instruction.SELECT.as?.kind!=="runtime-variable"||instruction.SELECT.as.expression!=="$id"||
    instruction.RETURN?.kind!=="runtime-expression"||
    instruction.RETURN.expression!=="$options[$id].id")
  fail("INVALID_INTERFACE","Selection binding contract does not match v0.2.0 compiled format");
 if(!Array.isArray(document.operations)||!document.operations.length||
    document.operations.some(x=>!c.nonempty(x))||
    new Set(document.operations).size!==document.operations.length)
  fail("INVALID_INTERFACE","Introductory interface operations invalid");
 return {schema:document.schema,menu:document.menu,operations:document.operations};
}'''
if s.count(old)!=1: raise SystemExit('Expected hardcoded intro menu not found; abort')
app.write_text(s.replace(old,new,1))
spec=Path('workspaces/programs/scratchpad/SRS.md')
doc=spec.read_text()
if 'SP-18' in doc: raise SystemExit('SP-18 already exists')
anchor='- **SEC-01:**'
if doc.count(anchor)!=1: raise SystemExit('SRS requirement insertion anchor failed')
req='''- **SP-18:** The Scratchpad introductory selection interface SHALL be maintained as a valid JSON artifact in the application workspace, with a filename derived from selection.shortTitle and a suffix identifying the interface type (currently \`-selection\`). The application SHALL dynamically discover the introductory interface by role, validate its filename against shortTitle, and render the JSON-defined menu rather than hard-coded JavaScript options. Renaming shortTitle and the matching file SHALL not require modifying the application logic.
'''
doc=doc.replace(anchor,req+anchor,1)
if '**Specification:** TP-SRS-001, v1.1.0' in doc:
 doc=doc.replace('**Specification:** TP-SRS-001, v1.1.0','**Specification:** TP-SRS-001, v1.2.0',1)
else: raise SystemExit('Unexpected SRS version')
spec.write_text(doc)
machine=Path('workspaces/programs/scratchpad/SRS.agent.json')
m=json.loads(machine.read_text())
if any(x.get('id')=='SP-18' for x in m.get('requirements',[])): raise SystemExit('Machine requirement already exists')
m['version']='1.2.0'
m['source']['revision']='1.2.0'
m['requirements'].append({"id":"SP-18","behavior":"The introductory application selection interface is a valid JSON file discovered by role in the application workspace; its filename is exactly selection.shortTitle + .json, and shortTitle ends with the interface type suffix -selection. The menu is loaded and validated at runtime, not hardcoded."})
m.setdefault('data',{})['intro_interface']={"directory":"workspaces/programs/scratchpad","role":"intro","filename_rule":"<selection.shortTitle>.json","short_title_type_suffix":"-selection","schema":"terminals.scratchpad.operation-menu.v1"}
machine.write_text(json.dumps(m,indent=2)+'\n')
print(json.dumps({"application":str(app),"specification_revision":"1.2.0","intro_interface":'workspaces/programs/scratchpad/Scratchpad-selection.json',"short_title":"Scratchpad-selection"}))

__PATCH_INTRO__
