node -e 'const a=require("/tmp/current-intro.json");if(a.menu.selection.shortTitle!=="Scratchpad-selection"||a.menu.selection.options.length!==5)throw Error("Intro output mismatch");console.log("INTRO_FROM_JSON_OK "+a.menu.selection.shortTitle)'
for file in workspaces/programs/scratchpad/Scratchpad-selection.json workspaces/programs/scratchpad/scratchpad-interface.test.js workspaces/programs/scratchpad/scratchpad.js workspaces/programs/scratchpad/SRS.md workspaces/programs/scratchpad/SRS.agent.json; do
  existing="$(gh api "repos/BestNameYet/Terminals/contents/$file" --jq .sha 2>/dev/null || true)"
  if test -n "$existing"; then
    oldhash="$(git show "HEAD:$file" | sha256sum | cut -d' ' -f1)"
    remotehash="$(gh api "repos/BestNameYet/Terminals/contents/$file" --jq .content | tr -d '\n' | base64 -d | sha256sum | cut -d' ' -f1)"
    if test "$oldhash" != "$remotehash"; then echo "HALT concurrent change: $file"; exit 2; fi
    commit="$(gh api --method PUT "repos/BestNameYet/Terminals/contents/$file" -f sha="$existing" -f message="Extract Scratchpad intro interface to shortTitle-named JSON: $file" -f content="$(base64 -w0 "$file")" --jq .commit.sha)"
  else
    commit="$(gh api --method PUT "repos/BestNameYet/Terminals/contents/$file" -f message="Create shortTitle-named Scratchpad JSON selection interface: $file" -f content="$(base64 -w0 "$file")" --jq .commit.sha)"
  fi
  gh api "repos/BestNameYet/Terminals/contents/$file" --jq .content | tr -d '\n' | base64 -d >/tmp/scratchpad-intro-verified
  cmp "$file" /tmp/scratchpad-intro-verified
  echo "READBACK_OK $file $commit"
done
